NEW_FILES = {'zoo_keeper/genome/species/planter.json': '{\n "species": "planter",\n "version": 1,\n "license": {\n  "construction_knowledge": "CC0",\n  "notes": "Minted 2026-10-27 by tools/new_species.py from \'prop\': a placeholder box at the authored dims until the recipe is shaped. NO REFERENCE GIVEN: look at ten photographs of one before drawing it."\n },\n "dimensions": {\n  "width": {\n   "min": 0.4,\n   "max": 0.9,\n   "default": 0.6\n  },\n  "depth": {\n   "min": 0.4,\n   "max": 0.9,\n   "default": 0.6\n  },\n  "height": {\n   "min": 0.8,\n   "max": 2.0,\n   "default": 1.5\n  }\n },\n "parts": [\n  "Planter_Body"\n ],\n "params": {},\n "materials": {\n  "default": "plaster",\n  "options": [\n   "concrete",\n   "metal",\n   "wood",\n   "plaster"\n  ]\n },\n "styles": {\n  "default": {\n   "material": "plaster",\n   "color": [\n    0.56,\n    0.55,\n    0.53\n   ],\n   "wear": 0.15,\n   "bevel": 0.006\n  },\n  "delco": {\n   "material": "plaster",\n   "color": [\n    0.5,\n    0.49,\n    0.46\n   ],\n   "wear": 0.35,\n   "bevel": 0.006,\n   "ambient": 0.35\n  },\n  "center_city": {\n   "material": "plaster",\n   "color": [\n    0.56,\n    0.5655,\n    0.58\n   ],\n   "wear": 0.122,\n   "bevel": 0.006,\n   "ambient": 0.15\n  },\n  "industrial_flats": {\n   "material": "plaster",\n   "color": [\n    0.4708,\n    0.4463,\n    0.4367\n   ],\n   "wear": 0.57,\n   "bevel": 0.006,\n   "ambient": 0.45\n  },\n  "rockay": {\n   "material": "plaster",\n   "color": [\n    0.5264,\n    0.5445,\n    0.5565\n   ],\n   "wear": 0.29,\n   "bevel": 0.006,\n   "ambient": 0.05\n  }\n },\n "budgets": {\n  "tris_lod0": 600\n },\n "attachments": [],\n "collision": true,\n "match_priority": 0,\n "keywords": [\n  "planter",\n  "potted_plant",\n  "plant_pot",\n  "potted plant",\n  "plant pot",\n  "lobby plant"\n ],\n "module_variants": 4\n}\n', 'zoo_keeper/genome/species/wall_clock.json': '{\n "species": "wall_clock",\n "version": 1,\n "license": {\n  "construction_knowledge": "CC0",\n  "notes": "Minted 2026-10-27 by tools/new_species.py from \'prop\': a placeholder box at the authored dims until the recipe is shaped. NO REFERENCE GIVEN: look at ten photographs of one before drawing it."\n },\n "dimensions": {\n  "width": {\n   "min": 0.25,\n   "max": 0.5,\n   "default": 0.36\n  },\n  "depth": {\n   "min": 0.04,\n   "max": 0.1,\n   "default": 0.06\n  },\n  "height": {\n   "min": 0.25,\n   "max": 0.5,\n   "default": 0.36\n  }\n },\n "parts": [\n  "WallClock_Body"\n ],\n "params": {},\n "materials": {\n  "default": "plastic",\n  "options": [\n   "concrete",\n   "metal",\n   "wood",\n   "plaster",\n   "plastic"\n  ]\n },\n "styles": {\n  "default": {\n   "material": "plastic",\n   "color": [\n    0.56,\n    0.55,\n    0.53\n   ],\n   "wear": 0.15,\n   "bevel": 0.006\n  },\n  "delco": {\n   "material": "plastic",\n   "color": [\n    0.5,\n    0.49,\n    0.46\n   ],\n   "wear": 0.35,\n   "bevel": 0.006,\n   "ambient": 0.35\n  },\n  "center_city": {\n   "material": "plastic",\n   "color": [\n    0.56,\n    0.5655,\n    0.58\n   ],\n   "wear": 0.122,\n   "bevel": 0.006,\n   "ambient": 0.15\n  },\n  "industrial_flats": {\n   "material": "plastic",\n   "color": [\n    0.4708,\n    0.4463,\n    0.4367\n   ],\n   "wear": 0.57,\n   "bevel": 0.006,\n   "ambient": 0.45\n  },\n  "rockay": {\n   "material": "plastic",\n   "color": [\n    0.5264,\n    0.5445,\n    0.5565\n   ],\n   "wear": 0.29,\n   "bevel": 0.006,\n   "ambient": 0.05\n  }\n },\n "budgets": {\n  "tris_lod0": 450\n },\n "attachments": [],\n "collision": false,\n "match_priority": 0,\n "keywords": [\n  "wall_clock",\n  "clock",\n  "wall clock",\n  "office clock"\n ],\n "connectors": {\n  "anchor": {\n   "type": "wall"\n  }\n }\n}\n', 'zoo_keeper/recipes/planter.py': '"""planter recipe: a lobby\'s potted plant -- a square planter, its soil, a plant on a stem or two.\n\nZoo 1.136.0, from the walker\'s bank comps (the factory\'s docs/reference/BANK_INTERIOR_COMPS.md, 2026-10-27): plants in\nplanters by the windows and the counters in comps 1, 4, 5 and 6 -- a ficus or a dracaena in a square pot, the\nfurniture a lobby keeps green. Minted by `tools/new_species.py`; shaped here.\n\nREFERENCE: the commercial interior planter of the 1980s-90s -- a square, slightly tapered box with a lip, soil a hand\nunder the lip, and a plant whose crown is a few rounded masses on a bare stem or two (a ficus) or tufts on canes (a\ndracaena). The VARIANT is the plant (four): its stems, how many crowns, where they sit.\n\nTWO MATERIALS: the planter (the plan\'s material) with its lip\'s shade as colour; and the plant, its soil, stems and\nleaves\' greens as COLOUR ONLY in the `Wear` vertex colour (`geometry.tint_wear`). Two submissions.\n\nRecipe frame: centre pivot. The module is exactly (w, d, h): the planter\'s base is the footprint and stands on the\nfloor, the tallest crown\'s top is the slot\'s top.\n"""\nfrom __future__ import annotations\n\nimport random\n\nfrom ..bpylayer import geometry, materials\n\nPOT_H_FRAC = 0.30        # the planter\'s height, of the slot\'s\nPOT_MAX_H = 0.55\nTAPER = 0.85             # the planter\'s foot, of its top\nLIP = 0.025              # the lip\'s height and how far it stands out\nRIM_W = 0.05             # the rim\'s bars, inward from the footprint\nRIM_STEP = 0.003         # the side bars this much lower at the top and higher at the foot than the long ones\nSOIL_T = 0.012           # the soil\'s thickness, down into the pot\nSOIL_PROUD = 0.004       # its surface this far above the pot\'s solid top\nSTEM_R = 0.018\nSTEM_ROOT = 0.012        # a stem\'s foot this far under the soil\'s surface, under the pot\'s top too\nBURY = 0.006\n\nLIP_RGB = (0.80, 0.78, 0.74)\nSOIL_RGB = (0.22, 0.16, 0.10)\nSTEM_RGB = (0.35, 0.26, 0.16)\nLEAF_RGB = ((0.16, 0.36, 0.12), (0.22, 0.44, 0.15), (0.12, 0.30, 0.10))\n#: variant -> (stems, crowns a stem): a ficus on one stem, two, a dracaena\'s three canes, a low bush\nPLANTS = ((1, 3), (2, 2), (3, 2), (1, 5))\n\n\ndef build(plan, streams, collection):\n    w = plan["dimensions"]["width"]\n    d = plan["dimensions"]["depth"]\n    h = plan["dimensions"]["height"]\n    bevel, wear = plan["bevel"], plan["wear"]\n    variant = int(plan.get("variant") or (plan.get("params") or {}).get("variant") or 0)\n    rng = streams.stream("wear")\n    lay = random.Random("planter:%d" % variant)\n    z0 = -h / 2.0\n    pot_h = min(POT_MAX_H, h * POT_H_FRAC)\n    pot_objs, plant_objs = [], []\n\n    def obj(bm, name, rgb, into, bev=0.0):\n        o = geometry.bm_to_object(bm, name, collection, bevel=bev, texel=1.2, rng=rng, wear=wear)\n        geometry.tint_wear(o, rgb)\n        into.append(o)\n\n    # the planter: a tapered square whose solid stops at the soil, its foot TAPER of its top. The first cut capped it\n    # with a solid lip the footprint wide, and the soil and the stems\' feet were inside it: a block, not a pot.\n    soil_z = z0 + pot_h - LIP                       # the soil\'s surface sits a lip under the rim\n    bm = geometry.new_bm()\n    verts = geometry.add_box(bm, (0.0, 0.0, (z0 + soil_z) / 2.0), (w - 2.0 * LIP, d - 2.0 * LIP, soil_z - z0))\n    for v in verts:\n        if v.co.z < (z0 + soil_z) / 2.0:\n            v.co.x *= TAPER\n            v.co.y *= TAPER\n    obj(bm, "Planter_Pot", (1.0, 1.0, 1.0), pot_objs, bevel)\n    # the rim: a ring of four bars the footprint wide, overhanging the pot by LIP, its foot a bury into the pot. The\n    # side bars run between the long ones, into them by a bury, a few mm lower at top and foot so no two faces share\n    # a plane at the corners.\n    rz0, rz1 = soil_z - BURY, z0 + pot_h\n    bm = geometry.new_bm()\n    for s in (-1.0, 1.0):\n        geometry.add_box(bm, (0.0, s * (d / 2.0 - RIM_W / 2.0), (rz0 + rz1) / 2.0), (w, RIM_W, rz1 - rz0))\n        # its outer face RIM_STEP inside the long bars\' ends, which share the footprint\'s edge\n        geometry.add_box(bm, (s * (w / 2.0 - RIM_W / 2.0 - RIM_STEP), 0.0, (rz0 + rz1) / 2.0),\n                         (RIM_W, d - 2.0 * RIM_W + 2.0 * BURY, rz1 - rz0 - 2.0 * RIM_STEP))\n    obj(bm, "Planter_Lip", LIP_RGB, pot_objs)\n    # the soil inside the ring, a hand of earth just proud of the pot\'s top and into the ring\'s bars\n    bm = geometry.new_bm()\n    sz0, sz1 = soil_z - SOIL_T, soil_z + SOIL_PROUD\n    # twice a bury into the ring: at one, its edges were the side bars\' ends (the census\'s second reading)\n    geometry.add_box(bm, (0.0, 0.0, (sz0 + sz1) / 2.0),\n                     (w - 2.0 * RIM_W + 4.0 * BURY, d - 2.0 * RIM_W + 4.0 * BURY, sz1 - sz0))\n    obj(bm, "Planter_Soil", SOIL_RGB, plant_objs)\n    soil_z = sz1\n    # the plant: stems from the soil, crowns on them, the tallest crown\'s top the slot\'s top\n    stems, crowns = PLANTS[variant % len(PLANTS)]\n    top = h / 2.0\n    spread = min(w, d) / 2.0 - LIP\n    bm_stem, bm_leaf = geometry.new_bm(), geometry.new_bm()\n    for s in range(stems):\n        sx = (s - (stems - 1) / 2.0) * spread * 0.5 + (lay.random() - 0.5) * 0.05\n        sy = (lay.random() - 0.5) * spread * 0.4\n        crown_r = min(spread * 1.1, (top - soil_z) * 0.22)\n        stem_top = top - crown_r * (1.0 + 0.6 * lay.random() * (s > 0))\n        # rooted STEM_ROOT into the soil: at a bury, a stem\'s foot stood 2 mm under the pot\'s top (the census\'s third)\n        geometry.add_cylinder(bm_stem, (sx, sy, (soil_z - STEM_ROOT + stem_top) / 2.0), STEM_R,\n                              stem_top - soil_z + STEM_ROOT,\n                              segments=6)\n        for c in range(crowns):\n            f = (c + 1.0) / crowns\n            cz = soil_z + (stem_top - soil_z) * (0.45 + 0.55 * f)\n            cr = crown_r * (0.65 + 0.35 * f)\n            ox = (lay.random() - 0.5) * cr * 0.8\n            oy = (lay.random() - 0.5) * cr * 0.8\n            cx = max(-w / 2.0 + cr, min(w / 2.0 - cr, sx + ox))\n            cy = max(-d / 2.0 + cr, min(d / 2.0 - cr, sy + oy))\n            cz = min(cz, top - cr)\n            verts = geometry.add_ellipsoid(bm_leaf, (cx, cy, cz), (cr, cr, cr * 0.85), u_seg=8, v_seg=5)\n            geometry.jitter_verts(verts, rng, cr * 0.12)\n    # THE CROWNS FILL THE SLOT AND STAY IN IT: jittered, a lump can stand past the slot or the tallest fall short of\n    # its top, and a module is its slot exactly. Lift the crowns until the highest touches the top, then hold every\n    # leaf inside the slot\'s box.\n    lv = list(bm_leaf.verts)\n    if lv:\n        lift = top - max(v.co.z for v in lv)\n        for v in lv:\n            v.co.z = min(top, v.co.z + lift)\n            v.co.x = max(-w / 2.0, min(w / 2.0, v.co.x))\n            v.co.y = max(-d / 2.0, min(d / 2.0, v.co.y))\n    obj(bm_stem, "Planter_Stems", STEM_RGB, plant_objs)\n    o = geometry.bm_to_object(bm_leaf, "Planter_Leaves", collection, bevel=0.0, texel=1.2, rng=rng, wear=wear)\n    geometry.tint_wear(o, LEAF_RGB[variant % len(LEAF_RGB)])\n    plant_objs.append(o)\n    pot = materials.make_material(f"M_Planter_{plan[\'material\']}", plan["color"], plan["material"])\n    leaves = materials.make_material("M_Planter_plant", (1.0, 1.0, 1.0), "plastic")\n    materials.assign(pot_objs, pot)\n    materials.assign(plant_objs, leaves)\n    return {"objects": pot_objs + plant_objs,\n            # the planter collides; a body brushes through the leaves\n            "collision_boxes": [((-w / 2.0, -d / 2.0, -h / 2.0), (w / 2.0, d / 2.0, z0 + pot_h))],\n            "attachments": {"ATT_top": (0.0, 0.0, h / 2.0)}}\n', 'zoo_keeper/recipes/wall_clock.py': '"""wall_clock recipe: a round office wall clock -- a dark rim, a white face, twelve hour marks, two hands.\n\nZoo 1.136.0, from the walker\'s bank comps (the factory\'s docs/reference/BANK_INTERIOR_COMPS.md, 2026-10-27): "a date\nclock over the line (2, 4), a wall clock" -- the round schoolhouse clock every 1990s branch hung over its teller line\nand in its back office. Minted by `tools/new_species.py`; shaped here.\n\nONE MATERIAL: the rim\'s dark, the face\'s white and the hands\' and marks\' black are COLOUR ONLY, in the `Wear` vertex\ncolour (`geometry.tint_wear`): one submission. The hands stand at ten past ten, the catalogue photograph\'s time, so a\nclock never reads as stopped at a time someone chose.\n\nRecipe frame: centre pivot, the wall at +Y and the face looking into the room at -Y (`security_camera`\'s convention).\nThe module is exactly (w, d, h): the rim\'s disc is the width and the height, its depth the slot\'s depth.\n"""\nfrom __future__ import annotations\n\nimport math\n\nfrom ..bpylayer import geometry, materials\n\nSEGMENTS = 24            # a round face that reads round from across a lobby\nRIM = 0.035              # the rim\'s width, the face inside it\nFACE_IN = 0.018          # the face this far inside the rim\'s front: deep enough that the hands stay in the slot\n#: an hour mark: width, depth, length. Its depth is two census tolerances and more: half buried in the face, half\n#: proud of it, each side clear of the face\'s plane by more than 2.2 mm\nMARK = (0.010, 0.008, 0.030)\n#: the plate\'s edge this far inside the bezel: at 0.5 % of the radius it was a millimetre, inside the census\'s 2.2\nPLATE_IN = 0.005\n#: the minute hand stands this far in front of the hour hand and the marks, so the two never share a plane\nHAND_STEP = 0.011\nHAND_T = 0.006\nBURY = 0.004\nBACK_GAP = 0.006         # the back plate\'s front this far behind the face\'s\n\nRIM_RGB = (0.08, 0.08, 0.09)\nFACE_RGB = (0.95, 0.94, 0.90)\nINK_RGB = (0.04, 0.04, 0.04)\n\n\ndef build(plan, streams, collection):\n    w = plan["dimensions"]["width"]\n    d = plan["dimensions"]["depth"]\n    h = plan["dimensions"]["height"]\n    bevel, wear = plan["bevel"], plan["wear"]\n    rng = streams.stream("wear")\n    r = min(w, h) / 2.0\n    y_front = -d / 2.0\n    objs = []\n\n    def obj(bm, name, rgb):\n        o = geometry.bm_to_object(bm, name, collection, bevel=0.0, texel=1.2, rng=rng, wear=wear)\n        geometry.tint_wear(o, rgb)\n        objs.append(o)\n\n    # the rim: an open bezel the slot\'s whole depth (no caps, so the face shows through it) and a back plate the\n    # full radius behind the face, whose ring between the face and the bezel is the rim a lobby reads\n    face_y0 = y_front + FACE_IN\n    bm = geometry.new_bm()\n    geometry.add_cylinder(bm, (0.0, 0.0, 0.0), r, d, segments=SEGMENTS, axis="Y", cap=False)\n    plate_y0 = face_y0 + BACK_GAP\n    geometry.add_cylinder(bm, (0.0, (plate_y0 + d / 2.0) / 2.0, 0.0), r - PLATE_IN, d / 2.0 - plate_y0,\n                          segments=SEGMENTS, axis="Y")\n    obj(bm, "WallClock_Rim", RIM_RGB)\n    # the face: a thin white disc inside the rim, its front FACE_IN behind the bezel\'s, into the back plate\n    bm = geometry.new_bm()\n    geometry.add_cylinder(bm, (0.0, (face_y0 + plate_y0 + BURY) / 2.0, 0.0), r - RIM, plate_y0 + BURY - face_y0,\n                          segments=SEGMENTS, axis="Y")\n    obj(bm, "WallClock_Face", FACE_RGB)\n    # twelve hour marks and two hands, standing proud of the face by their depth\n    ink_y = face_y0 - 0.0005                    # 4.5 mm proud of the face, 3.5 mm into it\n    bm = geometry.new_bm()\n    mr = r - RIM - MARK[2] / 2.0 - 0.008\n    for k in range(12):\n        a = math.radians(30.0 * k)\n        verts = geometry.add_box(bm, (0.0, 0.0, 0.0), (MARK[0], MARK[1], MARK[2]))\n        rot = _rot_y(-a)\n        for v in verts:\n            x, z = v.co.x, v.co.z\n            v.co.x = x * rot[0] + z * rot[1] + mr * math.sin(a)\n            v.co.z = x * rot[2] + z * rot[3] + mr * math.cos(a)\n            v.co.y += ink_y\n    # ten past ten: the hour hand at 10:10, the minute hand at 2\n    for length, frac, ang in ((0.50, 1.0, 305.0), (0.75, 0.8, 60.0)):\n        hl = (r - RIM) * length\n        verts = geometry.add_box(bm, (0.0, 0.0, 0.0), (HAND_T * 2.0 * frac + 0.006, MARK[1], hl))\n        a = math.radians(ang)\n        rot = _rot_y(-a)\n        for v in verts:\n            x, z = v.co.x, v.co.z + hl / 2.0\n            v.co.x = x * rot[0] + z * rot[1]\n            v.co.z = x * rot[2] + z * rot[3]\n            v.co.y += ink_y - (HAND_STEP if frac < 1.0 else 0.0)\n    obj(bm, "WallClock_Ink", INK_RGB)\n    surface = materials.make_material(f"M_WallClock_{plan[\'material\']}", plan["color"], plan["material"])\n    materials.assign(objs, surface)\n    return {"objects": objs, "collision_boxes": [((-w / 2.0, -d / 2.0, -h / 2.0), (w / 2.0, d / 2.0, h / 2.0))],\n            "attachments": {"ATT_back": (0.0, d / 2.0, 0.0)}}\n\n\ndef _rot_y(a):\n    """(xx, xz, zx, zz) of a turn by ``a`` in the face\'s plane (x, z)."""\n    c, s = math.cos(a), math.sin(a)\n    return (c, s, -s, c)\n', 'tests/test_planter.py': '"""planter: minted 2026-10-27 by tools/new_species.py (roadmap 150), shaped for the walker\'s bank comps (the factory\'s\ndocs/reference/BANK_INTERIOR_COMPS.md: plants in planters by the windows and counters in comps 1, 4, 5 and 6). The\npure half plans it; the bpy half builds it. FAILS ON 1.135.0, which has no planter. Run inside Blender for the shape:\n\n    blender -b --factory-startup --python-expr "import sys, pytest; sys.path.insert(0, \'.\'); print(\'rc\', int(pytest.main([\'-q\', \'-p\', \'no:cacheprovider\', \'tests/test_planter.py\'])))"\n"""\nimport pytest\n\nfrom zoo_keeper.core import genome, intent, kit\n\n\ndef test_planter_is_discovered_validates_and_is_asked_for_by_name():\n    assert "planter" in genome.list_species()\n    assert genome.validate_genome(genome.load_species("planter")) == []\n    assert intent.parse("potted plant").species == "planter"\n\n\ndef _plan(dims=(0.6, 0.6, 1.5), variant=0):\n    slot = {"slot_id": "planter_0", "role": "prop", "size_mod": "full", "style": 1,\n            "species": "planter", "fit": {"dims": list(dims), "pivot": "center"}}\n    if variant:\n        slot["variant"] = variant\n    return kit.plan_kit({"building_id": "t", "slots": [slot]}, theme="delco", style=1)\n\n\ndef test_planter_plans_and_its_variant_is_the_plant():\n    plan = _plan()\n    assert plan["species_fallbacks"] == [] and plan["modules"][0]["species"] == "planter"\n    assert genome.load_species("planter")["module_variants"] == 4\n    assert _plan(variant=2)["modules"][0]["stem"] != plan["modules"][0]["stem"]\n\n\ndef _build(tmp_path, dims, variant=0):\n    import bpy\n    from mathutils import Vector\n    from zoo_keeper.bpylayer import build as B\n    for o in list(bpy.data.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n    m = _plan(dims, variant)["modules"][0]\n    B.build_module(m, str(tmp_path / m["stem"]), theme="delco", style=1, options={"save_blend": False})\n    meshes = [o for o in bpy.data.objects if o.type == "MESH" and not o.name.endswith("-colonly")]\n    pts = [o.matrix_world @ Vector(c) for o in meshes for c in o.bound_box]\n    return meshes, pts\n\n\n@pytest.mark.parametrize("dims,variant", [((0.4, 0.4, 0.8), 0), ((0.6, 0.6, 1.5), 2), ((0.9, 0.9, 2.0), 3)])\ndef test_bpy_a_planter_is_its_slot_on_two_materials_with_soil_showing(tmp_path, dims, variant):\n    pytest.importorskip("bpy")\n    meshes, pts = _build(tmp_path, dims, variant)\n    for axis, size in enumerate(dims):\n        lo, hi = min(p[axis] for p in pts), max(p[axis] for p in pts)\n        assert hi - lo == pytest.approx(size, abs=0.02), (axis, lo, hi)\n    assert len({s.material.name for o in meshes for s in o.material_slots}) == 2\n    names = {o.name.split(".")[0] for o in meshes}\n    assert {"Planter_Pot", "Planter_Lip", "Planter_Soil", "Planter_Stems", "Planter_Leaves"} <= names, names\n    # the soil stands above the pot\'s solid: the first cut capped the pot and buried it\n    top = {o.name.split(".")[0]: max((o.matrix_world @ v.co).z for v in o.data.vertices) for o in meshes}\n    assert top["Planter_Soil"] > top["Planter_Pot"]\n', 'tests/test_wall_clock.py': '"""wall_clock: minted 2026-10-27 by tools/new_species.py (roadmap 150), shaped for the walker\'s bank comps (the\nfactory\'s docs/reference/BANK_INTERIOR_COMPS.md: "a date clock over the line (2, 4), a wall clock"). The pure half plans\nit; the bpy half builds it. FAILS ON 1.135.0, which has no wall clock. Run inside Blender for the shape:\n\n    blender -b --factory-startup --python-expr "import sys, pytest; sys.path.insert(0, \'.\'); print(\'rc\', int(pytest.main([\'-q\', \'-p\', \'no:cacheprovider\', \'tests/test_wall_clock.py\'])))"\n"""\nimport pytest\n\nfrom zoo_keeper.core import genome, intent, kit\n\n\ndef test_wall_clock_is_discovered_validates_and_is_asked_for_by_name():\n    assert "wall_clock" in genome.list_species()\n    g = genome.load_species("wall_clock")\n    assert genome.validate_genome(g) == []\n    assert intent.parse("wall clock").species == "wall_clock"\n    # hung on a wall, out of reach: no collision\n    assert g["collision"] is False and g["connectors"]["anchor"]["type"] == "wall"\n\n\ndef _plan(dims=(0.36, 0.06, 0.36)):\n    slot = {"slot_id": "wall_clock_0", "role": "prop", "size_mod": "full", "style": 1,\n            "species": "wall_clock", "fit": {"dims": list(dims), "pivot": "center"}}\n    return kit.plan_kit({"building_id": "t", "slots": [slot]}, theme="delco", style=1)\n\n\ndef test_wall_clock_plans_at_its_authored_dims():\n    plan = _plan()\n    assert plan["species_fallbacks"] == [] and plan["modules"][0]["species"] == "wall_clock"\n\n\n@pytest.mark.parametrize("dims", [(0.25, 0.04, 0.25), (0.36, 0.06, 0.36), (0.5, 0.1, 0.5)])\ndef test_bpy_a_clock_is_its_slot_on_one_material_its_face_toward_the_room(tmp_path, dims):\n    pytest.importorskip("bpy")\n    import bpy\n    from mathutils import Vector\n    from zoo_keeper.bpylayer import build as B\n    for o in list(bpy.data.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n    m = _plan(dims)["modules"][0]\n    B.build_module(m, str(tmp_path / m["stem"]), theme="delco", style=1, options={"save_blend": False})\n    meshes = [o for o in bpy.data.objects if o.type == "MESH" and not o.name.endswith("-colonly")]\n    pts = [o.matrix_world @ Vector(c) for o in meshes for c in o.bound_box]\n    for axis, size in enumerate(dims):\n        lo, hi = min(p[axis] for p in pts), max(p[axis] for p in pts)\n        assert hi - lo == pytest.approx(size, abs=0.02), (axis, lo, hi)\n    assert len({s.material.name for o in meshes for s in o.material_slots}) == 1\n    # the hands and marks stand in front of the face, toward -Y, the room\n    front = {o.name.split(".")[0]: min((o.matrix_world @ v.co).y for v in o.data.vertices) for o in meshes}\n    assert front["WallClock_Ink"] < front["WallClock_Face"]\n'}
CHANGELOG = '## [1.136.0] - `planter` and `wall_clock`: a lobby\'s plants and its clock\n\nThe walker, shown the bank\'s furnished lobby: "fix it before we rush to the release". Against the comps (the factory\'s\ndocs/reference/BANK_INTERIOR_COMPS.md) its 390 m2 floor was nearly empty. The comps keep plants in planters by the\nwindows and counters (comps 1, 4, 5, 6) and a clock over the teller line (2, 4), and the library had neither.\n\n### Added\n- **`planter`**, minted by `tools/new_species.py` and shaped. A square commercial planter, slightly tapered, under a\n  rim that overhangs it, with its soil recessed inside the rim and a plant on one to three bare stems, its crown a few\n  rounded masses.\n  - The VARIANT is the plant (four): a ficus on one stem, two, a dracaena\'s three canes, a low bush.\n  - The crowns are lifted until the tallest touches the slot\'s top and held inside its box, so the module is its slot.\n  - The pot collides; a body brushes through the leaves.\n  - Two materials: the pot (the plan\'s material); and the soil, stems and leaves as colour on one.\n  - 0.4-0.9 m square and 0.8-2.0 m tall, 320-560 tris.\n- **`wall_clock`**, minted and shaped. A round office clock: an open bezel and a back plate (the dark rim), a white\n  face, twelve hour marks and two hands standing at ten past ten.\n  - On a wall, its face to the room (-Y, `security_camera`\'s convention). No collision.\n  - One material, every colour in the vertex colour. 0.25-0.5 m across, 408 tris.\n- Both can be asked for by name ("potted plant", "wall clock").\n\n### Tests\n- `tests/test_planter.py`:\n  - discovered, validates, asked for by name;\n  - a variant a different module;\n  - built in Blender at three sizes: its slot on two materials, every part present, the soil above the pot\'s solid.\n- `tests/test_wall_clock.py`:\n  - discovered, validates, asked for by name, hung without collision;\n  - built at three sizes: its slot on one material, its hands in front of its face.\n- `tests/test_coincident_faces.py`: `CENSUS_BUILDS` 429 -> 435. The census reads 0 pairs at all six corners. The first\n  readings are recorded beside the count:\n  - the planter\'s lip on its pot;\n  - its ring\'s corners and soil edges;\n  - a stem\'s foot 2 mm under the pot\'s top;\n  - the clock\'s back plate a millimetre inside its bezel, and its marks and hands on one another\'s planes.\n\n  Both new files fail on 1.135.0. The bpy half passed 100, with 1 xfail, in Blender 5.1.1.\n\n'
OLD_VERSION, NEW_VERSION = '1.135.0', '1.136.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
